const baseUrl = 'http://localhost:5026/api';

export const server_calls = {

    items: async () => {
        const response = await fetch(`${baseUrl}/items.json`);
        let data = await response.json();
        return data;
    },

    notamon: async () => {
        const response = await fetch(`${baseUrl}/notamon.json`);
        let data = await response.json();
        return data;
    },

    singleNotamon: async (notamon) => {
        const response = await fetch(`${baseUrl}/notamon.json`);
        let data = await response.json();
        let singleNotamon = data.filter(function(notamonData) {
            return notamonData.name.toLowerCase() === notamon;
        });
        return singleNotamon[0];
    },

    status: async () => {
        const response = await fetch(`${baseUrl}/statusEffect.json`);
        let data = await response.json();
        return data;
    },

    type: async () => {
        const response = await fetch(`${baseUrl}/typeEffectiveness.json`);
        let data = await response.json();
        return data;
    },

    vaults: async () => {
        const response = await fetch(`${baseUrl}/vault.json`);
        let data = await response.json();
        return data;
    },

    keys: async () => {
        const response = await fetch(`${baseUrl}/key.json`);
        let data = await response.json();
        return data;    
    }

}
